// Keep this ID when retransmitting the same operation. Use a new ID only for a new operation.
const request = {request_id: 'replace-with-stable-host-operation-id', task_type: 'chat.general',
  prompt: '한 문장으로 인사해 주세요.', sync: true, input: {}};
const tasks = ['blog.tags','blog.summary','portfolio.search','ui.render','comment.generate','document.analyze','code.analyze','chat.general'];
if (!tasks.includes(request.task_type) || !request.request_id || !request.prompt) throw new Error('AI 요청을 확인하세요.');
// For RAG, input.collection is a logical name such as document. Platform namespaces it from the key.
return [{json:request}];

const result = $input.first().json;
const request = $('고정 요청 ID·작업 선택').first().json;
if (result.request_id !== request.request_id || result.task_type !== request.task_type ||
    !['running','succeeded','failed','cancelled'].includes(result.status) || !result.id)
  throw new Error('AI 작업 응답 계약이 다릅니다. 다시 실행하지 말고 요청 ID를 조회하세요.');
return [{json:result}];
